mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM workout_routines wr
    JOIN trainers t ON t.id = wr.trainer_id
    WHERE wr.id = #{routineId} AND wr.member_id = #{memberId}
      AND wr.status = 'ACTIVE' AND t.user_id = #{userId}
)

